// 깊은 트리에서 터지는 형태
function walk(node) { visit(node); node.children.forEach(walk); }

// 힙에 스택을 두면 한계가 사라진다(메모리가 허락하는 만큼)
function walkIter(root) {
  const stack = [root];
  while (stack.length) {
    const n = stack.pop();
    visit(n);
    for (let i = n.children.length - 1; i >= 0; i--) stack.push(n.children[i]);
  }
}

