function mount(el) {
  const ac = new AbortController();
  const timer = setInterval(tick, 1000);
  window.addEventListener('resize', onResize, { signal: ac.signal });

  return function dispose() {      // 만든 쪽이 치우는 함수를 돌려준다
    ac.abort();
    clearInterval(timer);
  };
}

